359				m, cmd := step(t, m, portsRefreshMsg{})
360	
361				if cmd == nil {
362					t.Fatal("a refresh request returned no command")
363				}
364				// Not run: it would read the real socket table. Its code is the closure
365				// fetchPortsCmd returns (the name survives inlining), not a batch that
366				// also re-arms the tick, nor a tea.Tick.
367				if name := runtime.FuncForPC(reflect.ValueOf(cmd).Pointer()).Name(); !strings.Contains(name, "fetchPortsCmd") {
